<?php
declare(strict_types=1);
define('BASE_PATH',dirname(__DIR__));require BASE_PATH.'/app/Support/helpers.php';require BASE_PATH.'/app/Foundation/Environment.php';App\Foundation\Environment::load(BASE_PATH.'/.env');$config=require BASE_PATH.'/config/database.php';$testDb='gbu_seed_test_'.bin2hex(random_bytes(4));if(!preg_match('/^gbu_seed_test_[a-f0-9]{8}$/',$testDb))throw new RuntimeException('Unsafe test database name.');$pdo=new PDO("mysql:host={$config['host']};port={$config['port']};charset=utf8mb4",$config['username'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>true]);
try{$pdo->exec(str_replace('gbu_exam_operations',$testDb,file_get_contents(BASE_PATH.'/database/schema.sql')));$seed=str_replace('gbu_exam_operations',$testDb,file_get_contents(BASE_PATH.'/database/seed.sql'));$pdo->exec($seed);$pdo->exec($seed);$pdo->exec("USE `{$testDb}`");$courses=(int)$pdo->query('SELECT COUNT(*) FROM courses')->fetchColumn();$mappings=(int)$pdo->query("SELECT COUNT(*) FROM programme_courses pc JOIN programmes p ON p.id=pc.programme_id WHERE p.code='UCS'")->fetchColumn();$roles=(int)$pdo->query('SELECT COUNT(*) FROM roles')->fetchColumn();assert($courses===87);assert($mappings===94);assert($roles===8);echo "Seed: PASS (repeatable, 8 roles, 87 unique courses, 94 UCS semester mappings)\n";}finally{$pdo->exec("DROP DATABASE IF EXISTS `{$testDb}`");}
